---@class SettingVoiceMgr
local SettingVoiceMgr = {}

-- 下载状态
local DLState = {
    None = 0,
    UnDownloaded = 1,               -- 未下载
    Downloading = 2,                -- 下载中
    DownloadingPaused = 3,          -- 下载中但是暂停了
    HasDownloadedButNotUsed = 4,    -- 下载完成并且没有使用过
    HasDownloadedAndUsed = 5,       -- 下载完成并且已经使用过
    HasDownloadedAndHasUpdate = 6,  -- 已下载但是有更新
}

local DefaultVoiceTag = "jp"

