local VoiceListFilePrefix = "werwer"
local VoiceListFileName = {
    ["zh"] = "sdfsdf",
    ["en"] = "dfgdfg",
    ["jp"] = "fghfgh",
}

local ListFileSaveDir = "Audio/_tag_"
local MetaFileSaveDir = "Audio/_tag_"

local DownloadStateKey = "HasVoiceDownload_"
local CurrentVoiceTagKey = "CurrentLocalizeVoiceTag"


function SettingVoiceMgr:Init()
    self:CleanProperties()
    self:InitVoiceList()
    self:InitVoiceState()
    -- cs_coroutine.start(Bind(self, self.UpdateDownloadedVoiceState))
    -- cs_coroutine.start(Bind(self, self.UpdateUndownloadedVoiceCount))
    -- 设置界面不用等这里更新的完成，更新完成以后会有语音包状态变更事件，只要注册事件进行变更就可以了
end

function SettingVoiceMgr:Clear()
    self:CleanProperties()
end

function SettingVoiceMgr:CleanProperties()
    self.LocalizeVoiceList = nil
    self.voiceDownloaderDict = nil      -- 下载器dict
    self.voiceStateDict = nil           -- 下载状态dict
    self.voiceDownloadCountDict = nil   -- 语音包需要下载的音频文件总数dict
end

function SettingVoiceMgr:InitVoiceList()
    self.LocalizeVoiceList = {}
    local isChineseVoiceOpen = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 56)).num) == 1
    if isChineseVoiceOpen then
        table.insert(self.LocalizeVoiceList, {
            voiceTag = "cn",
            GetVoiceName = function() return localize("汉语") end,
        })
    end
    table.insert(self.LocalizeVoiceList, {
        voiceTag = "jp",
        GetVoiceName = function() return localize("日语") end,
    })
end

--- 当前是否正使用默认语音包
function SettingVoiceMgr:IsCurrentUseDefaultVoice()
    return self:GetCurrentVoiceTag() == DefaultVoiceTag
end

--- 获取当前正在使用的语音包
function SettingVoiceMgr:GetCurrentVoiceTag()
    return PlayerPrefsUtility.GetEncryptedString(CurrentVoiceTagKey, DefaultVoiceTag)
end

--- 设置当前正在使用的语音包
---@param voiceTag any
function SettingVoiceMgr:SetCurrentVoiceTag(voiceTag)
    PlayerPrefsUtility.SetEncryptedString(CurrentVoiceTagKey, voiceTag)
end

--- 初始化各个语音包当前的状态
function SettingVoiceMgr:InitVoiceState()
    self.voiceStateDict = {}
    for i, voiceInfo in ipairs(self.LocalizeVoiceList) do
        local voiceTag = voiceInfo.voiceTag
        -- local defaultState = voiceTag == DefaultVoiceTag and DLState.HasDownloadedAndUsed or DLState.UnDownloaded
        -- local state = PlayerPrefsUtility.GetEncryptedInt(DownloadStateKey..voiceTag, defaultState)
        -- self.voiceStateDict[voiceTag] = state
        self.voiceStateDict[voiceTag] = DLState.HasDownloadedAndUsed
    end
end

--- 请求单个语音包的listFile
---@param voiceTag any
---@param requireResult any
function SettingVoiceMgr:RequireListFile(voiceTag, requireResult)
    requireResult.isError = false
    requireResult.finished = false
    requireResult.isNeedDownload = false
    local url = self:GetListFileUrl(voiceTag)
    local listFileSavePath = self:GetListFileSavePath(voiceTag)
    local savePathTmp = listFileSavePath .. ".PreTmp"   -- list文件保存为PreTmp后缀，防止和下载器使用的tmp后缀重复导致不能正常下载
    local metaFileSaveDir = self:GetMetaFileSaveDir(voiceTag)
    local fileSyncer = FileSyncer(url, savePathTmp, metaFileSaveDir, true)
    fileSyncer:SetFinishCallback(function(syncer)
        requireResult.finished = true
        requireResult.isError = syncer.IsError
        requireResult.isNeedDownload = syncer.IsNeedDownload
    end)
    fileSyncer:Start()

    while not requireResult.finished do
        cs_coroutine.yield_return(nil)
    end

    -- 统计需要下载音频文件的总数
    requireResult.count = 0
    xTry(function()
        if File.Exists(savePathTmp) then
            local streamReader = StreamReader(savePathTmp)
            local line = streamReader:ReadLine()
            while not string.isEmpty(line) do
                line = string.trim(line)
                if not string.isEmpty(line)
                and not string.startsWith("-") then
                    requireResult.count = requireResult.count + 1
                end
                line = streamReader:ReadLine()
            end
            streamReader:Close()
        end
    end)

    -- 请求结束以后，删除listFile，只留下metaFile作为更新信息的检查即可
    if File.Exists(savePathTmp) then
       File.Delete(savePathTmp)
    end

    -- 有一个问题，假如我检查了更新，发现有更新，但是如果这次我没下载，那下次我再来检查更新就会发现没有更新了
    -- 目前的逻辑是检查到有更新以后，会本地写一个持久化变量，标记状态为有更新。没有更新的则不会修改状态。这样就也没有问题。
end

--- 获取未下载语音包的下载总数
function SettingVoiceMgr:UpdateUndownloadedVoiceCount()
    local requireResultDict = {}

    -- 请求未下载语音包的listFile，看下载总数
    for i, voiceInfo in ipairs(self.LocalizeVoiceList) do
        local voiceTag = voiceInfo.voiceTag
        if voiceTag ~= DefaultVoiceTag then
            local requireResult = {}
            if self:GetVoiceState(voiceTag) == DLState.UnDownloaded then
                requireResultDict[voiceTag] = requireResult
                self:RequireListFile(voiceTag, requireResult)
            end
        end
    end

    -- 等待全部请求完成
    local allFinished = false
    while not allFinished do
        allFinished = true
        for voiceTag, requireResult in pairs(requireResultDict) do
            if requireResult.finished == false then
                allFinished = false
            end
        end
    end

    -- 将语音包的下载数量
    for voiceTag, requireResult in pairs(requireResultDict) do
        if not requireResult.isError then
            if isNull(self.voiceDownloadCountDict) then
                self.voiceDownloadCountDict = {}
            end
            self.voiceDownloadCountDict[voiceTag] = requireResult.count
            Events.Broadcast(Constants.EventNames.SettingVoiceCountChanged, voiceTag, requireResult.count)
        end
    end
end

--- 更新已下载的语音包的更新状态
function SettingVoiceMgr:UpdateDownloadedVoiceState()
    local requireResultDict = {}

    -- 请求已下载语音包的listFile，看是否有更新
    for i, voiceInfo in ipairs(self.LocalizeVoiceList) do
        local voiceTag = voiceInfo.voiceTag
        if voiceTag ~= DefaultVoiceTag then
            local requireResult = {}
            if self:GetVoiceState(voiceTag) >= DLState.HasDownloadedButNotUsed then
                requireResultDict[voiceTag] = requireResult
                self:RequireListFile(voiceTag, requireResult)
            end
        end
    end

    -- 等待全部请求完成
    local allFinished = false
    while not allFinished do
        allFinished = true
        for voiceTag, requireResult in pairs(requireResultDict) do
            if requireResult.finished == false then
                allFinished = false
            end
        end
    end

    -- 将有更新的语音包状态设置为有更新
    for voiceTag, requireResult in pairs(requireResultDict) do
        if not requireResult.isError
        and requireResult.isNeedDownload then
            self:SetVoiceState(voiceTag, DLState.HasDownloadedAndHasUpdate)
        end
    end
end

--- 获取语音包需要下载的文件数量
---@param voiceTag any
function SettingVoiceMgr:GetVoiceCount(voiceTag)
    if isNull(self.voiceDownloadCountDict)
    or isNull(self.voiceDownloadCountDict[voiceTag]) then
        return 0
    end
    return self.voiceDownloadCountDict[voiceTag]
end

--- 获取语音包的下载状态
---@param voiceTag any
function SettingVoiceMgr:GetVoiceState(voiceTag)
    return self.voiceStateDict[voiceTag]
end

--- 修改语音包的状态
---@param voiceTag any
function SettingVoiceMgr:SetVoiceState(voiceTag, state)
    self.voiceStateDict[voiceTag] = state
    PlayerPrefsUtility.SetEncryptedInt(DownloadStateKey..voiceTag, state)
    Events.Broadcast(Constants.EventNames.SettingVoiceStateChanged, voiceTag, state)
end

--- 给一个语音包生成下载器，并开始下载
---@param voiceTag any
function SettingVoiceMgr:DownloadVoice(voiceTag)
    if not isNull(self.voiceDownloaderDict) 
    and not isNull(self.voiceDownloaderDict[voiceTag]) then
        return self.voiceDownloaderDict[voiceTag]
    end
    local batchSyncer = BatchSyncer(VoiceListFilePrefix, VoiceListFileName[voiceTag], ListFileSaveDir, MetaFileSaveDir, true)
    batchSyncer:SetFinishCallback(function(syncer)
        if not syncer.IsError then
            -- 修改语音包的状态
            local newState = voiceTag == self:GetCurrentVoiceTag() and DLState.HasDownloadedAndUsed or DLState.HasDownloadedButNotUsed
            self:SetVoiceState(voiceTag, newState)
        end
    end)
    batchSyncer:Start()
    if isNull(self.voiceDownloaderDict) then
        self.voiceDownloaderDict = {}
    end
    self.voiceDownloaderDict[voiceTag] = batchSyncer
    return batchSyncer
end

--- 获取一个语音包的下载进度
---@param voiceTag any
function SettingVoiceMgr:GetDownloadingProgress(voiceTag)
    if not isNull(self.voiceDownloaderDict) 
    and not isNull(self.voiceDownloaderDict[voiceTag]) then
        return self.voiceDownloaderDict[voiceTag].Progress
    end
    return 0
end

--- 获取listFile的下载url
---@param voiceTag any
function SettingVoiceMgr:GetListFileUrl(voiceTag)
    printError("语音包list文件的url还没有配置!!!")
    return VoiceListFilePrefix .. VoiceListFileName[voiceTag]
end

--- 获取listFile的保存位置
---@param voiceTag any
function SettingVoiceMgr:GetListFileSavePath(voiceTag)
    local saveDir = GameUtils.ReplaceStr(ListFileSaveDir, "_tag_", voiceTag)
    return saveDir .. "/" .. VoiceListFileName[voiceTag]
end

--- 获取metaFile的保存目录
---@param voiceTag any
function SettingVoiceMgr:GetMetaFileSaveDir(voiceTag)
    return GameUtils.ReplaceStr(MetaFileSaveDir, "_tag_", voiceTag)
end

return SettingVoiceMgr